BEGIN CSS
/* Keyline + Print Contrast Focus (zero-JS, opt-in) */
/* Utility classes: .sl-keyline, .sl-keyline-strong
   Stronger :focus-visible (escalates under prefers-contrast: more)
   Reduced-motion friendly; print-only hairline keylines; underline links
   Uninstall: remove the stylesheet <link>; no tracking. */
.sl-keyline { outline: 2px solid color-mix(in srgb, currentColor 35%, black 65%); outline-offset: 2px; border-radius: 8px; }
.sl-keyline-strong { outline: 3px solid color-mix(in srgb, currentColor 20%, black 80%); outline-offset: 2px; border-radius: 10px; }
:where(a,button,input,select,textarea,[role="button"],[tabindex]:not([tabindex="-1"])):focus-visible { outline: 3px solid color-mix(in srgb, #0b5fff 80%, black 20%); outline-offset: 3px; border-radius: 6px; }
@media (prefers-contrast: more){ :where(a,button,input,select,textarea,[role="button"],[tabindex]:not([tabindex="-1"])):focus-visible{ outline:3px solid #000; outline-offset:4px;} .sl-keyline,.sl-keyline-strong{ outline-color:#000;} }
@media (prefers-reduced-motion: reduce){ *{ animation:none!important; transition:none!important; scroll-behavior:auto!important; } }
@media print{ .sl-keyline,.sl-keyline-strong{ outline:0.5pt solid #000; outline-offset:2pt; border-radius:8pt;} a{ text-decoration:underline!important;} }
END CSS

